example.code:
// 三篇文档
// doc1: "Java 并发编程"   doc2: "Java 虚拟机"   doc3: "并发与分布式"

// 分词后的倒排索引（简化）
// Term      Posting List (docId:tf:position)
// java   →  [1:1:0, 2:1:0]
// 并发   →  [1:1:1, 3:1:0]
// 编程   →  [1:1:2]
// 虚拟机 →  [2:1:1]
// 分布式 →  [3:1:2]

// 查询 "java 并发"：取两个倒排表，OR 得 {1,2,3}，doc1 同时命中两词，BM25 得分最高
GET /articles/_search
{
  "query": { "match": { "title": "java 并发" } }
}

// mapping：全文检索用 text，精确过滤/聚合用 keyword
PUT /articles
{ "mappings": { "properties": {
    "title":  { "type": "text", "analyzer": "ik_max_word",
                "fields": { "raw": { "type": "keyword" } } },
    "author": { "type": "keyword" } } } }

// 创建索引：3 主分片、1 副本（共 6 个分片）
PUT /orders_2026_10
{
  "settings": {
    "number_of_shards": 3,
    "number_of_replicas": 1,
    "refresh_interval": "1s"
  },
  "mappings": {
    "properties": {
      "order_no":  { "type": "keyword" },
      "title":     { "type": "text", "analyzer": "ik_max_word" },
      "amount":    { "type": "scaled_float", "scaling_factor": 100 },
      "create_at": { "type": "date" }
    }
  }
}

// 副本可以动态调整（大促前扩读能力）
PUT /orders_2026_10/_settings
{ "number_of_replicas": 2 }

// 查看分片大小与分布
GET _cat/shards/orders_*?v&h=index,shard,prirep,state,store,node

PUT /product
{ "settings": { "analysis": {
    "filter": { "my_syn": { "type": "synonym", "synonyms": ["手机,移动电话", "笔记本,笔记本电脑"] } },
    "analyzer": { "ik_syn": { "tokenizer": "ik_smart", "filter": ["my_syn"] } } } },
  "mappings": { "properties": {
    "title": { "type": "text", "analyzer": "ik_max_word", "search_analyzer": "ik_syn" } } } }

GET /product/_search
{ "query": { "multi_match": { "query": "华为手机", "fields": ["title^3", "desc"] } } }
